const sharedLocalStorage = {};

// Exact reproduction of loadApp
function loadApp() {
  const w = new Window({ url: 'http://localhost/', settings: { disableJavaScriptFileLoading: true } });
  const doc = w.document;
  const origLS = w.localStorage;

  // Copy
  for (const k of Object.keys(sharedLocalStorage)) {
    origLS.setItem(k, sharedLocalStorage[k]);
  }

