  console.log('AFTER CLOSE: w.localStorage.getItem:', w.localStorage.getItem('todos-vanillajs'));

  // Eval
  w.eval(appSource);
  console.log('AFTER EVAL: origLS.getItem:', origLS.getItem('todos-vanillajs'));
  console.log('AFTER EVAL: w.localStorage.getItem:', w.localStorage.getItem('todos-vanillajs'));

