  w.dispatchEvent(new w.Event('load'));
  console.log('AFTER EVENTS: origLS.getItem:', origLS.getItem('todos-vanillajs'));
  console.log('AFTER EVENTS: w.localStorage.getItem:', w.localStorage.getItem('todos-vanillajs'));

  return { w, doc };
}

// Create scenario
sharedLocalStorage['todos-vanillajs'] = JSON.stringify([{id:1,title:'Buy groceries',completed:false}]);
loadApp();
